// Producer-Consumer using wait/notify — must be in synchronized!
package com.bank.objmethods;

import java.util.LinkedList;
import java.util.Queue;

public class TradeQueue {
    private final Queue<String> queue = new LinkedList<>();
    private final int capacity;

    public TradeQueue(int capacity) { this.capacity = capacity; }

    public synchronized void produce(String trade) throws InterruptedException {
        while (queue.size() == capacity) {
            wait();  // MUST be inside synchronized! Releases lock + suspends.
        }
        queue.add(trade);
        notifyAll();  // Wake consumers. MUST be inside synchronized!
    }

    public synchronized String consume() throws InterruptedException {
        while (queue.isEmpty()) {
            wait();  // MUST be inside synchronized!
        }
        String trade = queue.poll();
        notifyAll();  // Wake producers.
        return trade;
    }

    public synchronized int size() { return queue.size(); }
}
