// ─── File: src/test/java/com/bank/objmethods/ObjectMethodsTest.java ───
package com.bank.objmethods;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import static org.assertj.core.api.Assertions.*;

class ObjectMethodsTest {

    // ═══ getClass() — runtime type ═══
    @Test
    void getClass_returnsRuntimeType() {
        Object ref = new Account("SAV001", BigDecimal.ZERO);
        assertThat(ref.getClass().getSimpleName()).isEqualTo("Account");
        assertThat(ref.getClass().getName()).contains("Account");
        // getClass() returns ACTUAL type, not variable type (Object).
    }

    @Test
    void getClass_isFinal() throws NoSuchMethodException {
        var method = Object.class.getMethod("getClass");
        assertThat(java.lang.reflect.Modifier.isFinal(method.getModifiers())).isTrue();
        // getClass() is FINAL — cannot be overridden!
    }

    @Test
    void getClass_vsInstanceof() {
        Account account = new Account("SAV001", BigDecimal.ZERO);
        // getClass() == : EXACT type match (no subclasses)
        assertThat(account.getClass() == Account.class).isTrue();
        // instanceof: includes subclasses
        assertThat(account instanceof Object).isTrue();  // Account IS-A Object
    }

    // ═══ wait/notify — must be in synchronized ═══
    @Test
    void waitNotify_withoutSynchronized_throwsIllegalMonitor() {
        Object lock = new Object();
        assertThatThrownBy(() -> lock.wait())
            .isInstanceOf(IllegalMonitorStateException.class);
        // NOT in synchronized block → IllegalMonitorStateException!
    }

    @Test
    void waitNotify_insideSynchronized_works() throws InterruptedException {
        Object lock = new Object();
        Thread waiter = new Thread(() -> {
            synchronized (lock) {
                try { lock.wait(100); }  // wait with timeout (100ms)
                catch (InterruptedException e) { Thread.currentThread().interrupt(); }
            }
        });
        waiter.start();
        Thread.sleep(50);
        synchronized (lock) { lock.notify(); }  // notify the waiter
        waiter.join(500);
        assertThat(waiter.isAlive()).isFalse();  // waiter completed
    }

    // ═══ TradeQueue producer-consumer ═══
    @Test
    void tradeQueue_producerConsumer() throws InterruptedException {
        TradeQueue queue = new TradeQueue(3);

        // Producer thread:
        Thread producer = new Thread(() -> {
            try {
                queue.produce("TRD-001");
                queue.produce("TRD-002");
                queue.produce("TRD-003");
            } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        });

        producer.start();
        producer.join(1000);

        assertThat(queue.size()).isEqualTo(3);

        // Consumer:
        assertThat(queue.consume()).isEqualTo("TRD-001");
        assertThat(queue.consume()).isEqualTo("TRD-002");
        assertThat(queue.size()).isEqualTo(1);
    }

    // ═══ finalize() — deprecated ═══
    @Test
    void finalize_isDeprecated() throws NoSuchMethodException {
        var method = Object.class.getDeclaredMethod("finalize");
        assertThat(method.isAnnotationPresent(Deprecated.class)).isTrue();
        // finalize() is @Deprecated — use Cleaner or try-with-resources instead.
    }
}
```
